import { Pressable, StyleSheet, Text, View } from "react-native";
import type { GestureResponderEvent, StyleProp, TextStyle, ViewProps, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface BreadcrumbItem {
  label: string;
  /** Called when the crumb is pressed; navigate here with your router. The last crumb is the current page and is not pressable. */
  onPress?: (event: GestureResponderEvent) => void;
}

export interface BreadcrumbProps extends ViewProps {
  items: BreadcrumbItem[];
  /** Extend the inner, named parts of the breadcrumb: list, crumb, current or separator. The React Native counterpart of `classNames`. */
  styles?: {
    list?: StyleProp<ViewStyle>;
    crumb?: StyleProp<TextStyle>;
    current?: StyleProp<TextStyle>;
    separator?: StyleProp<TextStyle>;
  };
}

export function Breadcrumb({ items, style, styles: parts, ...props }: BreadcrumbProps) {
  const tokens = useTokens();

  return (
    <View {...props} accessibilityRole="header" style={[local.list, style, parts?.list]}>
      {items.map((item, index) => {
        const last = index === items.length - 1;
        return (
          <View key={`${item.label}-${index}`} style={local.crumb}>
            {last ? (
              <Text accessibilityRole="text" style={[local.text, { color: tokens.accentStrong, fontWeight: "500" }, parts?.current]}>
                {item.label}
              </Text>
            ) : (
              <Pressable accessibilityRole="link" hitSlop={8} onPress={item.onPress}>
                <Text style={[local.text, { color: tokens.textSecondary }, parts?.crumb]}>{item.label}</Text>
              </Pressable>
            )}
            {last ? null : <Text style={[local.separator, { color: tokens.borderStrong }, parts?.separator]}>›</Text>}
          </View>
        );
      })}
    </View>
  );
}

const local = StyleSheet.create({
  list: { flexDirection: "row", flexWrap: "wrap", alignItems: "center", rowGap: 2 },
  crumb: { flexDirection: "row", alignItems: "center" },
  text: { fontSize: metrics.text.sm, paddingVertical: 4 },
  separator: { fontSize: 18, marginHorizontal: 6 },
});

export default Breadcrumb;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
  /** Four distinguishable colours for chart series, the counterpart of --series-1 to --series-4. */
  series: [string, string, string, string];
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
  series: ["#1f7dcf", "#7128a5", "#e58f00", "#009e84"],
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
  series: ["#55adff", "#9c37be", "#e66e00", "#00a861"],
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
